    height,
    background: 'rgb(' + bg.r + ',' + bg.g + ',' + bg.b + ')',
    elements: list.map((f, i) => ({ id: i + 1, type: f.type, x: f.r.x, y: f.r.y, w: f.r.w, h: f.r.h })),
